const breeds = ['Beagle', 'Border Collie', 'Boxer', 'Dachshund', 'Poodle']

function BreedList({ query }) {
  const shown = breeds.filter(b => b.toLowerCase().includes(query.toLowerCase()))
  return <ul>{shown.map(b => <li key={b}>{b}</li>)}</ul>
}

export default BreedList
